class Solution {
public:
    int findLHS(vector<int>& nums) {
        unordered_map<int,int> cnt;
        for (int x : nums) cnt[x]++;
        int ans = 0;
        for (auto& [v, c] : cnt) {
            auto it = cnt.find(v + 1);
            if (it != cnt.end()) {
                ans = max(ans, c + it->second);
            }
        }
        return ans;
    }
};
